/* The theme marketplace and a plan set from /admin (round Z5). `theme_marketplace_listings`: one row per theme in the library's Browse themes and at storelib.com/themes, with its name, author and author photo, category, tier (free, paid with a price, or Pro plan only), cover, screenshots, the private path of its zip (checked and parsed by the import pipeline at upload), an optional demo store, published or hidden, and its place in the order. Anyone may read a published row; every write is the admin's, through the server. `creator_plan_overrides`: a plan an admin assigns a creator, over what they pay for, with the paid plan and status kept beside it. `admin_set_plan_override` writes the row and the creator's `subscription_plan_id` and `subscription_status` together, which every plan check already reads, and puts the paid plan back when it is cleared; the trigger `creators_plan_override_hold` keeps the override in those columns when a Stripe webhook or the billing sync writes a plan, and keeps the plan they wrote as the paid one. Stripe is never touched. The creator can read their own row, and it is in the realtime publication so their open app refreshes. Changes no existing row. Until it runs, the library and marketplace show Storelib's own theme, /admin/themes says to run it, and assigning a plan is refused with that reason. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.theme_marketplace_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,62}[a-z0-9])?$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80), author_name text NOT NULL DEFAULT 'Storelib' CHECK (char_length(author_name) BETWEEN 1 AND 80), author_avatar_url text, category text NOT NULL DEFAULT 'general', tier text NOT NULL DEFAULT 'free' CHECK (tier IN ('free', 'paid', 'pro')), price_cents integer NOT NULL DEFAULT 0 CHECK (price_cents >= 0 AND price_cents <= 1000000), cover_url text, screenshots text[] NOT NULL DEFAULT '{}', package_path text, package_kind text CHECK (package_kind IS NULL OR package_kind IN ('storelib', 'shopify', 'export')), builtin_theme_id uuid, demo_url text CHECK (demo_url IS NULL OR demo_url ~ '^https://'), published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.theme_marketplace_listings ENABLE ROW LEVEL SECURITY;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'theme_marketplace_listings' AND policyname = 'theme_marketplace_listings_read_published') THEN CREATE POLICY theme_marketplace_listings_read_published ON public.theme_marketplace_listings FOR SELECT TO anon, authenticated USING (published); END IF; END $do$;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.theme_marketplace_listings FROM anon, authenticated;
CREATE INDEX IF NOT EXISTS theme_marketplace_listings_order ON public.theme_marketplace_listings (published, sort_order);
CREATE TABLE IF NOT EXISTS public.creator_plan_overrides (creator_id uuid PRIMARY KEY REFERENCES public.creators(id) ON DELETE CASCADE, plan_id text CHECK (plan_id IS NULL OR plan_id IN ('free', 'growth', 'pro')), paid_plan_id text, paid_status text, set_at timestamptz NOT NULL DEFAULT now(), set_by text NOT NULL DEFAULT 'admin session');
ALTER TABLE public.creator_plan_overrides ENABLE ROW LEVEL SECURITY;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'creator_plan_overrides' AND policyname = 'creator_plan_overrides_read_own') THEN CREATE POLICY creator_plan_overrides_read_own ON public.creator_plan_overrides FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = auth.uid())); END IF; END $do$;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.creator_plan_overrides FROM anon, authenticated;
CREATE OR REPLACE FUNCTION public.storelib_plan_override_hold() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE o record; BEGIN IF coalesce(current_setting('storelib.plan_override_write', true), '') = 'on' THEN RETURN NEW; END IF; IF NEW.subscription_plan_id IS NOT DISTINCT FROM OLD.subscription_plan_id AND NEW.subscription_status IS NOT DISTINCT FROM OLD.subscription_status THEN RETURN NEW; END IF; SELECT plan_id, paid_plan_id, paid_status INTO o FROM public.creator_plan_overrides WHERE creator_id = NEW.id; IF NOT FOUND OR o.plan_id IS NULL THEN RETURN NEW; END IF; UPDATE public.creator_plan_overrides SET paid_plan_id = CASE WHEN NEW.subscription_plan_id IS DISTINCT FROM OLD.subscription_plan_id THEN NEW.subscription_plan_id ELSE paid_plan_id END, paid_status = CASE WHEN NEW.subscription_plan_id IS DISTINCT FROM OLD.subscription_plan_id OR NEW.subscription_status IS DISTINCT FROM OLD.subscription_status THEN NEW.subscription_status ELSE paid_status END WHERE creator_id = NEW.id; NEW.subscription_plan_id := o.plan_id; NEW.subscription_status := 'active'; RETURN NEW; END $f$;
REVOKE ALL ON FUNCTION public.storelib_plan_override_hold() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_plan_override_hold ON public.creators; CREATE TRIGGER creators_plan_override_hold BEFORE UPDATE OF subscription_plan_id, subscription_status ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_plan_override_hold(); END IF; END $do$;
CREATE OR REPLACE FUNCTION public.admin_set_plan_override(p_creator uuid, p_plan text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE c record; o record; v_had boolean; v_from text; v_paid text; BEGIN IF p_plan IS NOT NULL AND p_plan NOT IN ('free', 'growth', 'pro') THEN RAISE EXCEPTION 'unknown plan %', p_plan; END IF; SELECT id, subscription_plan_id, subscription_status INTO c FROM public.creators WHERE id = p_creator FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'no creator %', p_creator; END IF; SELECT plan_id, paid_plan_id, paid_status INTO o FROM public.creator_plan_overrides WHERE creator_id = p_creator FOR UPDATE; v_had := FOUND AND o.plan_id IS NOT NULL; PERFORM set_config('storelib.plan_override_write', 'on', true); IF p_plan IS NULL THEN IF NOT v_had THEN PERFORM set_config('storelib.plan_override_write', '', true); RETURN jsonb_build_object('from', NULL, 'to', NULL, 'paid_plan_id', c.subscription_plan_id, 'changed', false); END IF; UPDATE public.creators SET subscription_plan_id = coalesce(o.paid_plan_id, 'free'), subscription_status = coalesce(o.paid_status, 'active') WHERE id = p_creator; UPDATE public.creator_plan_overrides SET plan_id = NULL, set_at = now() WHERE creator_id = p_creator; PERFORM set_config('storelib.plan_override_write', '', true); RETURN jsonb_build_object('from', o.plan_id, 'to', NULL, 'paid_plan_id', coalesce(o.paid_plan_id, 'free'), 'changed', true); END IF; IF v_had THEN v_from := o.plan_id; v_paid := o.paid_plan_id; UPDATE public.creator_plan_overrides SET plan_id = p_plan, set_at = now() WHERE creator_id = p_creator; ELSE v_from := coalesce(c.subscription_plan_id, 'free'); v_paid := c.subscription_plan_id; INSERT INTO public.creator_plan_overrides (creator_id, plan_id, paid_plan_id, paid_status, set_at) VALUES (p_creator, p_plan, c.subscription_plan_id, c.subscription_status, now()) ON CONFLICT (creator_id) DO UPDATE SET plan_id = EXCLUDED.plan_id, paid_plan_id = EXCLUDED.paid_plan_id, paid_status = EXCLUDED.paid_status, set_at = now(); END IF; UPDATE public.creators SET subscription_plan_id = p_plan, subscription_status = 'active' WHERE id = p_creator; PERFORM set_config('storelib.plan_override_write', '', true); RETURN jsonb_build_object('from', v_from, 'to', p_plan, 'paid_plan_id', v_paid, 'changed', true); END $f$;
REVOKE ALL ON FUNCTION public.admin_set_plan_override(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_set_plan_override(uuid, text) TO service_role;
DO $do$ BEGIN IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'creator_plan_overrides') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.creator_plan_overrides; END IF; END $do$;
notify pgrst, 'reload schema';
